    FRUIT("fruit", "水果", "Fruit", "水果朋友", listOf("apple", "banana")),
    VEHICLES("vehicles", "交通工具", "Vehicles", "出发啦", listOf("bus", "car")),
    EVERYDAY("everyday", "生活用品", "Everyday Things", "身边的小物品", listOf("cup", "toothbrush")),
}

